use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/doubled-norm175";
fn main(){let binary=format!("{R}/target-new/release/probe");let out=Command::new("nm").args(["-S","--demangle",&binary]).output().unwrap();assert!(out.status.success());let mut rows=vec![];let mut raw=String::new();for line in String::from_utf8(out.stdout).unwrap().lines(){if !line.contains("probe::kernel::<"){continue;}let f=line.split_whitespace().collect::<Vec<_>>();let start=u64::from_str_radix(f[0],16).unwrap();let bytes=u64::from_str_radix(f[1],16).unwrap();let symbol=f[3..].join(" ");let out=Command::new("objdump").arg("-d").arg(format!("--start-address={start}")).arg(format!("--stop-address={}",start+bytes)).arg(&binary).output().unwrap();assert!(out.status.success());let asm=String::from_utf8(out.stdout).unwrap();let mut instructions=0;let mut ifma=0;let mut stack=0;let mut mask_add=0;for l in asm.lines(){let f=l.split('\t').collect::<Vec<_>>();if f.len()<3||!f[0].trim_end().ends_with(':'){continue;}let op=f[2].trim();if op.is_empty(){continue;}instructions+=1;if op.starts_with("vpmadd52"){ifma+=1;}if op.contains("%rsp"){stack+=1;}if op.starts_with("vpaddq")&&op.contains("%k"){mask_add+=1;}}rows.push(json!({"symbol":symbol,"bytes":bytes,"instructions":instructions,"IFMA_instructions":ifma,"RSP_relative_instructions":stack,"masked_vector_adds":mask_add}));raw+=&format!("{symbol}\n{asm}\n");}assert_eq!(rows.len(),8);let data=fs::read(&binary).unwrap();let review:Value=json!({"binary_sha256":format!("{:x}",Sha256::digest(data)),"postcapture_read_only_disassembly":true,"not_dynamic_counts_or_causal_attribution":true,"symbols":rows});fs::write(format!("{R}/codegen.json"),serde_json::to_vec_pretty(&review).unwrap()).unwrap();fs::write(format!("{R}/codegen.txt"),raw).unwrap();println!("{review}");}
